export interface RemainingFormat {
  separator?: string;
  showDays?: boolean;
}

function atLeastTwo(value: number): string {
  return String(value).padStart(2, "0");
}

export function formatRemaining(
  seconds: number,
  format: RemainingFormat = {},
): string {
  if (!Number.isFinite(seconds) || !Number.isInteger(seconds) || seconds < 0) {
    throw new RangeError("seconds must be a finite nonnegative integer");
  }

  const separator = format.separator ?? ":";
  const minutes = Math.floor(seconds / 60) % 60;
  const remainder = seconds % 60;

  if (format.showDays === true) {
    const days = Math.floor(seconds / 86_400);
    const hours = Math.floor(seconds / 3_600) % 24;
    return [days, hours, minutes, remainder].map(atLeastTwo).join(separator);
  }

  const hours = Math.floor(seconds / 3_600) % 24;
  return [hours, minutes, remainder].map(atLeastTwo).join(separator);
}

