import { formatRemaining, RemainingFormat } from "./solution";

function equal(actual: string, expected: string, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${expected}, got ${actual}`);
}

function expectRangeError(value: number, message: string): void {
  try {
    formatRemaining(value);
  } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

equal(formatRemaining(0), "00:00:00", "zero with defaults");
equal(formatRemaining(5), "00:00:05", "single-digit seconds");
equal(formatRemaining(3661), "01:01:01", "hours minutes and seconds");
equal(formatRemaining(24 * 3600), "24:00:00", "hours can exceed 23");
equal(formatRemaining(100 * 3600 + 2), "100:00:02", "hours have no upper bound");
equal(formatRemaining(90061, { showDays: true }), "01:01:01:01", "day format");
equal(formatRemaining(10 * 86400, { showDays: true, separator: " | " }), "10 | 00 | 00 | 00", "verbatim separator");
equal(formatRemaining(3723, { separator: "", showDays: false }), "010203", "empty separator is preserved");
equal(formatRemaining(59, { separator: "--" }), "00--00--59", "multi-character separator");

const configuration: RemainingFormat = { separator: "/", showDays: true };
Object.freeze(configuration);
equal(formatRemaining(86400, configuration), "01/00/00/00", "frozen configuration works");
equal(configuration.separator as string, "/", "separator is not changed");

expectRangeError(-1, "negative seconds");
expectRangeError(1.5, "fractional seconds");
expectRangeError(Number.NaN, "NaN seconds");
expectRangeError(Number.POSITIVE_INFINITY, "infinite seconds");

